int read_config_value(const char* config_key, const char* config_value, char* dest_buffer, size_t dest_size)
{
    // 检查参数有效性
    if (config_key == NULL || config_value == NULL || dest_buffer == NULL || dest_size == 0) {
        return -1;
    }

    // 获取配置值的长度
